export function normalizeSettings(v={}){return {nav:ordered(v.nav,NAV),widgets:ordered(v.widgets,WIDGETS),filters:ordered(v.filters,FILTERS),productFilterOrder:ordered(v.productFilterOrder,PRODUCT_FILTERS),navIcons:Object.fromEntries(Object.entries(v.navIcons||{}).filter(([id,icon])=>NAV.some(x=>x[0]===id)&&NAV_ICONS.some(x=>x[0]===icon))),hidden:(Array.isArray(v.hidden)?v.hidden:[]).filter(x=>WIDGETS.some(y=>y[0]===x)),fields:Array.isArray(v.fields)?v.fields.filter(x=>FIELDS.some(y=>y[0]===x)):['customer','time','status','total','items'],customerFields:Array.isArray(v.customerFields)?v.customerFields.filter(x=>['identity','group','first','address','average','count','created'].includes(x)):['identity','group','first','address','average','count','created'],view:v.view==='grid'?'grid':'list',productCosts:Object.fromEntries(Object.entries(v.productCosts||{}).filter(([id,n])=>/^[0-9a-f-]{36}$/i.test(id)&&Number.isSafeInteger(n)&&n>=0&&n<=2147483647))};}
