export function filterSellerOrders(orders,storeId,f={},query=''){return orders.filter(o=>o.mid===storeId&&(f.status===''||f.status===undefined||String(o.st)===f.status)&&(!f.address||o.cust.addr.toLowerCase().includes(f.address.toLowerCase()))&&(!f.product||o.items.some(i=>i.pid===f.product))&&(!f.from||new Date(o.ts)>=new Date(f.from+'T00:00:00+03:00'))&&(!f.to||new Date(o.ts)<new Date(new Date(f.to+'T00:00:00+03:00').getTime()+86400000))&&(!query||[o.id,o.cust.name,o.cust.phone,...o.items.map(i=>i.name)].join(' ').toLowerCase().includes(query.toLowerCase())));}
export function filterSellerProducts(products,storeId,f={},query=''){return products.filter(p=>p.mid===storeId&&(!f.category||(p.store_category||p.cat)===f.category||p.cat===f.category)&&(!f.stock||f.stock==='all'||(f.stock==='zero'?p.stock===0:f.stock==='low'?p.stock>0&&p.stock<=(p.threshold??5):p.stock>0))&&(!f.active||f.active==='all'||(f.active==='published'?p.active&&!p.blocked:!p.active||p.blocked))&&(!query||[p.name,p.sku,p.variant,p.desc].join(' ').toLowerCase().includes(query.toLowerCase())));}
