export function visibleSellerProducts(rows,storeId){const mine=rows.filter(p=>p.mid===storeId&&!p.attributes?._deleted),key=p=>[p.mid,p.name.trim(),p.cat,p.price,p.sku||'',p.variant||'',p.desc||''].join('\u001f');const current=new Set(mine.filter(p=>p.active||p.stock>0).map(key));const seen=new Set();return mine.filter(p=>{if(p.active||p.stock>0||p.blocked)return true;const k=key(p);if(current.has(k)||seen.has(k))return false;seen.add(k);return true;});}

