 // Customer store page in the site's own colours: store switcher, store card, category chips, product grid.
 // Opening hours in Baghdad time; a closing time before the opening time runs past midnight.
 function storeHours(s){
  const t=v=>{const m=/^(\d{1,2}):(\d{2})/.exec(String(v||''));return m?Number(m[1])*60+Number(m[2]):null},o=t(s.open_time),c=t(s.close_time);if(o==null||c==null)return null;
  const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Baghdad',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date()),now=Number(parts.find(p=>p.type==='hour').value)*60+Number(parts.find(p=>p.type==='minute').value);
  const open=o===c?true:o<c?now>=o&&now<c:now>=o||now<c;
  const f=v=>{const h=Math.floor(v/60),m=v%60;return (h%12||12)+':'+String(m).padStart(2,'0')+' '+(h<12?'ص':'م')};
  return {open,label:f(o)+' - '+f(c)};
 }
